() => {
  const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable_"]');
  const results = [];
  for (const card of cards) {
    const title = card.querySelector('span')?.textContent.trim() || '';
    const ratingEl = card.querySelector('[id^="mntl-recipe-star-rating_"]');
    let ratingText = '';
    if (ratingEl) {
      const ariaLabel = ratingEl.getAttribute('aria-label') || '';
      const title2 = ratingEl.getAttribute('title') || '';
      ratingText = `aria-label: "${ariaLabel}", title: "${title2}"`;
    }
    const ratingsCount = card.querySelector('div[class*="ratings-count"]')?.textContent.trim() || '';
    const meta = card.querySelector('[id^="mntl-recipe-card-meta_"]')?.textContent.trim().replace(/\s+/g,' ') || '';
    results.push({ title, rating: ratingText, meta });
  }
  return results;
}

() => {
  const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable_"]');
  const results = [];
  for (const card of cards) {
    const titleEl = card.querySelector('span');
    const title = titleEl ? titleEl.textContent.trim() : '';
    const ratingEl = card.querySelector('[id^="mntl-recipe-star-rating_"]');
    let ratingInfo = {};
    if (ratingEl) {
      ratingInfo.ariaLabel = ratingEl.getAttribute('aria-label');
      ratingInfo.title = ratingEl.getAttribute('title');
      ratingInfo.className = ratingEl.className;
      // Get all child SVG count
      ratingInfo.svgCount = ratingEl.querySelectorAll('svg').length;
    }
    results.push({ id: card.id, title, ratingInfo });
  }
  return JSON.stringify(results, null, 2);
}

