() => {
  // Get all relevant details from the recipe page
  const recipeName = document.querySelector('h1')?.textContent.trim() || '';
  const rating = document.querySelector('[id^="mm-recipes-review-bar__rating_"]')?.textContent.trim() || '';
  const reviewCount = document.querySelectorAll('[id^="mm-recipes-review-bar__rating-count"]');
  const totalTime = document.querySelector('[id*="total-time"]')?.textContent.trim() || '';

  // Find time details
  const timeElements = document.querySelectorAll('[class*="mntl-recipe-details__time"], [class*="recipe-details__time"]');
  const timeInfo = [];
  document.querySelectorAll('div').forEach(div => {
    const text = div.textContent.trim();
    if ((text.includes('Prep Time:') || text.includes('Cook Time:') || text.includes('Total Time:') || text.includes('Additional Time:')) && text.length < 200) {
      timeInfo.push(text);
    }
  });

  // Get the recipe description
  const desc = document.querySelector('p')?.textContent.trim() || '';

  // Get the submitter
  let submitter = '';
  document.querySelectorAll('div, span').forEach(el => {
    if (el.textContent.includes('Submitted by') && el.textContent.length < 200) {
      submitter = el.textContent.trim();
    }
  });

  return { recipeName, rating, timeInfo: timeInfo.slice(0, 10), desc: desc.substring(0, 300), submitter };
}
